let activeView = 'inicio';

let actividadResizeHandler = null;

const LANGUAGE_STORAGE_KEY = 'cerutti-language';

let currentLang = 'es';

const languageLabels = {
    es: 'Espanol',
    en: 'English',
    pt: 'Portugues'
};

function setLanguageOptionsWithFlags() {
    const langSelect = document.getElementById('langSelect');
    const trigger = document.getElementById('langTrigger');
    const switcher = document.getElementById('langSwitcher');
    if (!langSelect || !trigger || !switcher) return;

    Array.from(langSelect.options).forEach((option) => {
        const label = languageLabels[option.value];
        if (label) {
            option.textContent = label;
        }
    });

    const selectedValue = langSelect.value || 'es';
    const triggerLabel = trigger.querySelector('.lang-trigger-label');
    const triggerFlag = trigger.querySelector('.flag');

    if (triggerLabel) {
        triggerLabel.textContent = languageLabels[selectedValue] || languageLabels.es;
    }

    if (triggerFlag) {
        triggerFlag.className = `flag flag-${selectedValue}`;
    }

    switcher.querySelectorAll('.lang-menu-option').forEach((button) => {
        const isActive = button.dataset.value === selectedValue;
        button.classList.toggle('is-active', isActive);
        button.setAttribute('aria-selected', isActive ? 'true' : 'false');
    });
}

function getStoredLanguage() {
    try {
        const storedLanguage = window.localStorage.getItem(LANGUAGE_STORAGE_KEY);
        return i18n[storedLanguage] ? storedLanguage : 'es';
    } catch (error) {
        return 'es';
    }
}

function persistLanguage(lang) {
    try {
        window.localStorage.setItem(LANGUAGE_STORAGE_KEY, lang);
    } catch (error) {
        return;
    }
}

function goHome() {
    render('inicio');
    changeLanguage();
}

function initLanguageSwitcher() {
    const langSelect = document.getElementById('langSelect');
    const switcher = document.getElementById('langSwitcher');
    const trigger = document.getElementById('langTrigger');
    const options = document.querySelectorAll('.lang-menu-option');

    if (!langSelect || !switcher || !trigger || !options.length) return;

    trigger.addEventListener('click', () => {
        const isOpen = switcher.classList.toggle('is-open');
        trigger.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });

    options.forEach((button) => {
        button.addEventListener('click', () => {
            langSelect.value = button.dataset.value;
            switcher.classList.remove('is-open');
            trigger.setAttribute('aria-expanded', 'false');
            changeLanguage();
        });
    });

    document.addEventListener('click', (event) => {
        if (!switcher.contains(event.target)) {
            switcher.classList.remove('is-open');
            trigger.setAttribute('aria-expanded', 'false');
        }
    });

    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            switcher.classList.remove('is-open');
            trigger.setAttribute('aria-expanded', 'false');
        }
    });
}

function changeLanguage() {
    currentLang = document.getElementById('langSelect').value;
    persistLanguage(currentLang);
    const data = i18n[currentLang] || i18n.es;
    document.documentElement.lang = currentLang;
    
    document.getElementById('h-title').innerHTML = data.hTitle;
    document.getElementById('h-subtitle').innerText = data.hSubtitle;
    document.getElementById('btn-act').innerText = data.btnAct;
    document.getElementById('btn-con').innerText = data.btnCon;
    document.getElementById('showcase-title').innerText = data.showcaseTitle;
    document.getElementById('showcase-subtitle').innerText = data.showcaseSubtitle;
    document.getElementById('f-text').innerHTML = data.fText;

    const nav = document.getElementById('main-nav');
    const views_keys = ['inicio', 'productos', 'empresa', 'novedades', 'contacto'];
    nav.innerHTML = '';
    data.nav.forEach((text, i) => {
        const b = document.createElement('button');
        b.className = 'nav-link';
        b.innerText = text;
        b.onclick = () => views_keys[i] === 'inicio' ? goHome() : render(views_keys[i]);
        nav.appendChild(b);
    });

    updateActiveNavLink(activeView || 'inicio');

    setLanguageOptionsWithFlags();

    applyStaticTranslations(currentLang);

    if (activeView && activeView !== 'inicio') {
        render(activeView);
    }
}

function updateActiveNavLink(view) {
    const views_keys = ['inicio', 'productos', 'empresa', 'novedades', 'contacto'];
    const buttons = document.querySelectorAll('#main-nav .nav-link');
    buttons.forEach((btn, index) => {
        btn.classList.toggle('is-active', views_keys[index] === (view || 'inicio'));
    });
}

function applyStaticTranslations(lang) {
    const t = staticI18n[lang] || staticI18n.es;

    const setText = (selector, value) => {
        const el = document.querySelector(selector);
        if (el && value !== undefined) el.textContent = value;
    };

    const setHtml = (selector, value) => {
        const el = document.querySelector(selector);
        if (el && value !== undefined) el.innerHTML = value;
    };

    setText('#about-section .about-card-3d .about-subtitle', t.aboutSubtitle);
    setText('#about-section .about-card-3d .section-title', t.aboutTitle);
    setHtml('#about-section .about-text-content p:nth-child(1)', t.aboutP1);
    setHtml('#about-section .about-text-content p:nth-child(2)', t.aboutP2);

    setText('#innovation-section .tech-box .about-subtitle', t.innovationSubtitle);
    setText('#innovation-section .tech-box h2', t.innovationTitle);

    const innovationCards = document.querySelectorAll('#innovation-section .innovation-card');
    innovationCards.forEach((card, i) => {
        const item = t.innovaciónCards[i];
        if (!item) return;
        const sub = card.querySelector('.sub-header');
        const h3 = card.querySelector('h3');
        const p1 = card.querySelectorAll('p')[0];
        const p2 = card.querySelectorAll('p')[1];
        if (sub) sub.textContent = item.sub;
        if (h3) h3.textContent = item.title;
        if (p1) p1.innerHTML = item.p1;
        if (p2) p2.innerHTML = item.p2;
    });

    setText('#confianza .section-title', t.confianzaTitle);
    setText('#confianza .confianza-block:nth-of-type(1) .subtitulo-dorado', t.sociosTitle);
    setText('#confianza .confianza-block:nth-of-type(1) p', t.sociosDesc);
    setText('#confianza .confianza-block:nth-of-type(2) .subtitulo-dorado', t.respaldoTitle);
    setText('#confianza .confianza-block:nth-of-type(2) p', t.respaldoDesc);

    setText('#quality-section > .about-subtitle', t.calidadSub);
    setText('#quality-section > h2', t.calidadTitle);
    setHtml('#quality-section .quality-card:nth-child(1) p', t.calidadP1);
    setText('#quality-section .quality-card:nth-child(2) h3', t.calidadT2);
    setHtml('#quality-section .quality-card:nth-child(2) p', t.calidadP2);
    setText('#quality-section .quality-card:nth-child(3) h3', t.calidadT3);
    setHtml('#quality-section .quality-card:nth-child(3) p', t.calidadP3);

    setText('.site-footer .footer-col:first-child .footer-heading:nth-of-type(1)', t.footerSocial);
    setText('.site-footer .footer-col:first-child .footer-heading:nth-of-type(2)', t.footerCorreo);
    setHtml('.footer-address', t.footerAddress);

    const footerNav = document.querySelectorAll('.footer-nav-col a');
    footerNav.forEach((link, i) => {
        if (t.footerNav[i]) link.textContent = t.footerNav[i];
    });

    const legalLinks = document.querySelectorAll('.footer-nav-col .legal-link');
    legalLinks.forEach((link, i) => {
        if (t.legalLinks && t.legalLinks[i]) link.textContent = t.legalLinks[i];
    });

    const tagTranslations = {
        es: { BLANDO: 'BLANDO', SEMIDURO: 'SEMIDURO', DURO: 'DURO' },
        en: { BLANDO: 'SOFT', SEMIDURO: 'SEMI-HARD', DURO: 'HARD' },
        pt: { BLANDO: 'MACIO', SEMIDURO: 'SEMIDURO', DURO: 'DURO' }
    };

    const dict = tagTranslations[lang] || tagTranslations.es;
    document.querySelectorAll('#carousel-section .product-3d-card .tag').forEach((tagEl) => {
        const cat = tagEl.dataset.cat;
        if (cat && dict[cat]) {
            tagEl.textContent = dict[cat];
        }
    });
}

function animateValue(obj, start, end, duration) {
    let startTimestamp = null;
    const step = (timestamp) => {
        if (!startTimestamp) startTimestamp = timestamp;
        const progress = Math.min((timestamp - startTimestamp) / duration, 1);
        obj.innerHTML = Math.floor(progress * (end - start) + start).toLocaleString();
        if (progress < 1) {
            window.requestAnimationFrame(step);
        }
    };
    window.requestAnimationFrame(step);
}

function render(view) {
    activeView = view || 'inicio';
    updateActiveNavLink(activeView);
    const container = document.getElementById('main-view');
    const heroMain = document.getElementById('hero-main');
    const carouselSection = document.getElementById('carousel-section');
    const aboutSection = document.getElementById('about-section');
    const innovationSection = document.getElementById('innovation-section');
    
    // --- NUEVAS SECCIONES A OCULTAR ---
    const confianzaSection = document.getElementById('confianza');
    const qualitySection = document.getElementById('quality-section');

    // Header activo según sección
    const header = document.querySelector('header');
    header.classList.remove('header-actividad-style');
    if (view === 'nosotros') {
        header.classList.add('header-actividad-style');
    }
    
    // 1. OCULTAR TODO POR DEFECTO
    if (heroMain) heroMain.style.display = 'none';
    if (carouselSection) carouselSection.style.display = 'none';
    if (aboutSection) aboutSection.style.display = 'none';
    if (innovationSection) innovationSection.style.display = 'none';
    if (confianzaSection) confianzaSection.style.display = 'none'; // OCULTAR CONFIANZA
    if (qualitySection) qualitySection.style.display = 'none';     // OCULTAR CALIDAD
    
    container.innerHTML = '';

    // 2. LÓGICA DE VISUALIZACIÓN
    if (!view || view === 'inicio') {
        // Estamos en el Inicio: Mostrar todo
        if (heroMain) heroMain.style.display = '';
        if (carouselSection) carouselSection.style.display = '';
        if (aboutSection) aboutSection.style.display = '';
        if (innovationSection) innovationSection.style.display = '';
        if (confianzaSection) confianzaSection.style.display = ''; // MOSTRAR EN INICIO
        if (qualitySection) qualitySection.style.display = '';     // MOSTRAR EN INICIO
    } else {
        // Contenido dinámico para otras pestañas
        const data = (i18n[currentLang] || i18n.es).sections;
        
        if (view === 'productos') {
            renderProductos(container);
        } else if (view === 'empresa') {
            renderEmpresa(container, data.empresa);
        } else if (view === 'novedades') {
            renderNovedades(container, data.novedades);
        } else if (view === 'contacto') {
            renderContacto(container, data.contacto);
        } else if (view === 'nosotros') {
            renderActividad(container, data.actividad);
        }
    }

    window.scrollTo({ top: 0, behavior: 'smooth' });
}

function bindContactoFormSubmissions(container) {
    const forms = container.querySelectorAll('.clientes-form');

    forms.forEach((form) => {
        form.addEventListener('submit', async (event) => {
            event.preventDefault();

            const formText = getContactoFormTexts();
            const submitButton = form.querySelector('button[type="submit"]');
            let feedback = form.querySelector('.form-feedback');

            if (!feedback) {
                feedback = document.createElement('p');
                feedback.className = 'form-feedback';
                form.appendChild(feedback);
            }

            feedback.textContent = formText.statusSending;
            feedback.className = 'form-feedback form-feedback--sending';

            if (submitButton) {
                submitButton.disabled = true;
                submitButton.classList.add('is-loading');
            }

            try {
                const response = await fetch(form.action, {
                    method: form.method || 'POST',
                    body: new FormData(form),
                    headers: {
                        Accept: 'application/json'
                    }
                });

                if (!response.ok) {
                    throw new Error('submit_failed');
                }

                form.reset();
                feedback.textContent = formText.statusSent;
                feedback.className = 'form-feedback form-feedback--sent';
            } catch (error) {
                feedback.textContent = formText.statusError;
                feedback.className = 'form-feedback form-feedback--error';
            } finally {
                if (submitButton) {
                    submitButton.disabled = false;
                    submitButton.classList.remove('is-loading');
                }
            }
        });
    });
}

function renderActividad(container, data) {
    container.innerHTML = `
        <section id="nuestra-actividad-industrial">
            <div class="header-spacer-industrial"></div>
            <div class="contenedor-principal-industrial">
                <div class="columna-texto-industrial">
                    <h2 class="titulo-fijo-industrial">${data.title}</h2>
                    ${data.desc1}
                </div>
                <div class="columna-fotos-industrial">
                    <div class="tarjeta-imagen-industrial-3d">
                        <img src="img/quesoplantacerutti2.png" alt="Vanguardia Láctea">
                    </div>
                    <div class="tarjeta-imagen-industrial-3d">
                        <img src="img/tripleplantacerutti.png" alt="Proceso de Salmuera">
                    </div>
                    <div class="tarjeta-imagen-industrial-3d">
                        <img src="img/vistaaereaplanta.png" alt="Infraestructura Regional">
                    </div>
                </div>
            </div>
        </section>`;

    const textCards = container.querySelectorAll('.tarjeta-texto-industrial-3d');
    const imageCards = container.querySelectorAll('.tarjeta-imagen-industrial-3d');
    const photosColumn = container.querySelector('.columna-fotos-industrial');
    const mainContainer = container.querySelector('.contenedor-principal-industrial');

    const syncActividadCardHeights = () => {
        const isMobile = window.innerWidth <= 1024;

        if (photosColumn) {
            if (isMobile) {
                photosColumn.style.paddingTop = '0px';
                photosColumn.style.gap = '22px';
            } else {
                const firstTextCard = textCards[0];
                if (firstTextCard && mainContainer) {
                    const baseTop = mainContainer.getBoundingClientRect().top;
                    const cardTop = firstTextCard.getBoundingClientRect().top;
                    const cardGap = window.getComputedStyle(firstTextCard).marginBottom;
                    photosColumn.style.paddingTop = `${Math.max(0, Math.round(cardTop - baseTop))}px`;
                    photosColumn.style.gap = cardGap;
                }
            }
        }

        imageCards.forEach((card, index) => {
            if (isMobile) {
                card.style.height = 'auto';
                return;
            }

            const textCard = textCards[index];
            card.style.height = textCard ? `${textCard.offsetHeight}px` : 'auto';
        });
    };

    if (actividadResizeHandler) {
        window.removeEventListener('resize', actividadResizeHandler);
    }

    actividadResizeHandler = syncActividadCardHeights;
    window.addEventListener('resize', actividadResizeHandler);
    container.querySelectorAll('.columna-fotos-industrial img').forEach((img) => {
        if (!img.complete) {
            img.addEventListener('load', syncActividadCardHeights, { once: true });
        }
    });
    requestAnimationFrame(syncActividadCardHeights);
}

