function initSectionTitleMotion() {
    const titleSelector = '#about-section .section-title, #innovation-section .tech-box h2, #confianza .section-title, #quality-section h2';
    const titles = document.querySelectorAll(titleSelector);

    if (!titles.length) {
        return;
    }

    titles.forEach((title) => title.classList.add('section-title-reveal'));

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        titles.forEach((title) => title.classList.add('in-view'));
        return;
    }

    const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                entry.target.classList.add('in-view');
            }
        });
    }, {
        threshold: 0.35,
        rootMargin: '0px 0px -10% 0px'
    });

    titles.forEach((title) => observer.observe(title));
}

function initCursorFx() {
    const isFinePointer = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    if (!isFinePointer) return;

    const ring = document.createElement('div');
    ring.className = 'cursor-fx-ring';

    const dot = document.createElement('div');
    dot.className = 'cursor-fx-dot';

    document.body.appendChild(ring);
    document.body.appendChild(dot);

    let mouseX = window.innerWidth / 2;
    let mouseY = window.innerHeight / 2;
    let ringX = mouseX;
    let ringY = mouseY;
    let isVisible = false;

    const animate = () => {
        ringX += (mouseX - ringX) * 0.2;
        ringY += (mouseY - ringY) * 0.2;

        ring.style.transform = `translate(${ringX}px, ${ringY}px) translate(-50%, -50%)`;
        dot.style.transform = `translate(${mouseX}px, ${mouseY}px) translate(-50%, -50%)`;

        requestAnimationFrame(animate);
    };

    document.addEventListener('mousemove', (event) => {
        mouseX = event.clientX;
        mouseY = event.clientY;

        if (!isVisible) {
            isVisible = true;
            document.body.classList.add('cursor-fx-active');
        }

        const hoverTarget = event.target.closest('a, button, .nav-link, .product-card, .lang-menu-option, .lang-trigger');
        document.body.classList.toggle('cursor-fx-hover', !!hoverTarget);
    });

    document.addEventListener('mouseleave', () => {
        document.body.classList.remove('cursor-fx-active', 'cursor-fx-hover');
        isVisible = false;
    });

    animate();
}

window.onload = () => {
    currentLang = getStoredLanguage();
    const langSelect = document.getElementById('langSelect');
    if (langSelect) {
        langSelect.value = currentLang;
    }
    initLanguageSwitcher();
    setLanguageOptionsWithFlags();
    changeLanguage();
    initSectionTitleMotion();
    initCursorFx();
};